UPDATE product
product_name = #{productName}, category_id = #{categoryId}, category_name = #{categoryName}, images = #{images}, infos = #{infos}, price = #{price}, shipping_price = #{shippingPrice}, modified_at = #{modifiedAt}, modified_by = #{modifiedBy}
